#![allow(
    clippy::too_many_lines,
    clippy::cast_sign_loss,
    clippy::match_same_arms,
    clippy::unreachable,
    missing_docs
)]
//! @generated by `xgen` — `ds:` print strings with `0x01..0x04`
//! control codes resolved to draw lists (the `cs:0x6709` interpreter
//! compiled). Plain strings take the live scan instead.

/// One emitted glyph — char + entry-relative cursor + `pace` flag.
#[derive(Clone, Copy)]
pub struct Draw {
    /// The glyph byte.
    pub ch: u8,
    /// `bx` delta from the entry cursor.
    pub bx: i16,
    /// `dx` delta from the entry cursor.
    pub dx: i16,
    /// The direct-char typewriter gate (repeat fills skip it).
    pub pace: bool,
}

/// A decoded string — draws plus the net `bx` the print returns.
pub struct Dec {
    /// Emitted draws, in order.
    pub draws: &'static [Draw],
    /// Net `bx` delta the `cs:0x6709` return carries.
    pub bx: i16,
    /// The first 4 source bytes — a staleness check: the compiled
    /// list only replays while the live bytes still match.
    pub sig: [u8; 4],
}

mod s0;
mod s1;
mod s2;
mod s3;
mod s4;
mod s5;
mod s6;
mod s7;
mod s8;
mod s9;

/// The decoded string at `a`, if `a` holds control codes.
pub fn at(a: u16) -> Option<&'static Dec> {
    match a {
        0x00AE..=0x1B0C => s0::f(a),
        0x1B0D..=0x25D1 => s1::f(a),
        0x25D2..=0x2DAA => s2::f(a),
        0x2DAB..=0x327A => s3::f(a),
        0x327B..=0x4190 => s4::f(a),
        0x4191..=0x4F74 => s5::f(a),
        0x4F75..=0x6900 => s6::f(a),
        0x6901..=0x6B8F => s7::f(a),
        0x6B90..=0x738C => s8::f(a),
        0x738D..=0xFFFF => s9::f(a),
        _ => None,
    }
}
